<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Concerns\HasUuids;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Illuminate\Database\Eloquent\Relations\HasMany;use Illuminate\Database\Eloquent\SoftDeletes;
class Product extends Model {use HasUuids,SoftDeletes;public $incrementing=false;protected $keyType='string';protected $fillable=['organization_id','category_id','therapeutic_family_id','base_unit_id','dosage_form_id','administration_route_id','code','name','generic_name','product_type','strength','packaging','description','is_controlled','is_active'];protected function casts():array{return ['is_controlled'=>'boolean','is_active'=>'boolean'];}public function organization():BelongsTo{return $this->belongsTo(Organization::class);}public function category():BelongsTo{return $this->belongsTo(CatalogReference::class,'category_id');}public function therapeuticFamily():BelongsTo{return $this->belongsTo(CatalogReference::class,'therapeutic_family_id');}public function baseUnit():BelongsTo{return $this->belongsTo(CatalogReference::class,'base_unit_id');}public function dosageForm():BelongsTo{return $this->belongsTo(CatalogReference::class,'dosage_form_id');}public function administrationRoute():BelongsTo{return $this->belongsTo(CatalogReference::class,'administration_route_id');}public function codes():HasMany{return $this->hasMany(ProductCode::class);}public function batches():HasMany{return $this->hasMany(Batch::class);}}
